const raw = $json.data ?? $json;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
if (!text || !text.trim()) {
  return [{ json: { category: 'unknown', candidates: [], error: 'Discovery Agent returned an empty response for this category' } }];
}
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1 || end < start) {
  return [{ json: { category: 'unknown', candidates: [], error: 'Discovery Agent did not return JSON: ' + text.slice(0, 300) } }];
}
const cleaned = text.slice(start, end + 1);
try {
  return [{ json: JSON.parse(cleaned) }];
} catch (e) {
  return [{ json: { category: 'unknown', candidates: [], error: 'Malformed JSON from Discovery Agent: ' + e.message } }];
}

const discovery = $json;
const diet = $('Parse Request').item.json.diet;
const quantity = $('Parse Request').item.json.quantity;
return [{ json: { chatInput: JSON.stringify({ category: discovery.category, notes: discovery.notes || '', candidates: discovery.candidates || [], error: discovery.error || null, diet: diet, quantity: quantity }) } }];

const MEAT_FISH = ['chicken','beef','pork','lamb','turkey','duck','bacon','ham','sausage','gelatin','lard','anchovy','shrimp','shellfish','fish','tuna','salmon','meat','veal'];
const ANIMAL = ['milk','cheese','butter','cream','whey','egg','honey','yogurt'];
const text = (query.ingredientsText || '').toLowerCase();
const diet = query.diet;
let excluded = [];
if (diet === 'vegan') excluded = [...MEAT_FISH, ...ANIMAL];
else if (diet === 'veg' || diet === 'eggetarian') excluded = MEAT_FISH;
else if (diet === 'pescatarian') excluded = MEAT_FISH.filter(k => !['fish','tuna','salmon','anchovy','shrimp','shellfish'].includes(k));
return JSON.stringify({ conflicts: excluded.filter(k => text.includes(k)) });
